let timer = null;
let dotNetRef = null;
let isIdle = false;
let timeoutMs = 0;
let listeners = [];

const events = ['mousemove', 'keydown', 'click', 'scroll'];

function onActivity() {
    if (isIdle) {
        isIdle = false;
        dotNetRef.invokeMethodAsync('OnActiveCallback');
    }
    resetTimer();
}

function resetTimer() {
    clearTimeout(timer);
    timer = setTimeout(() => {
        isIdle = true;
        dotNetRef.invokeMethodAsync('OnIdleCallback');
    }, timeoutMs);
}

export function init(element, ref, timeoutSeconds) {
    dotNetRef = ref;
    timeoutMs = timeoutSeconds * 1000;
    isIdle = false;

    events.forEach(evt => {
        const handler = onActivity;
        element.addEventListener(evt, handler, { passive: true });
        document.addEventListener(evt, handler, { passive: true });
        listeners.push({ evt, handler });
    });

    resetTimer();
}

export function dispose() {
    clearTimeout(timer);
    timer = null;

    const element = listeners.length > 0 ? undefined : null;

    // Each event was registered on both element and document.
    // The element may already be removed from the DOM, so we only
    // need to clean up document-level listeners.  Removed elements
    // automatically drop their listeners.
    listeners.forEach(({ evt, handler }) => {
        document.removeEventListener(evt, handler);
    });
    listeners = [];
    dotNetRef = null;
    isIdle = false;
}

